/* 本次治疗方案药品/疗法目录（按字段规格 PDF）
 * 西药：WESTERN_CATALOG 药物分类 → [{ name 药品名称, doses 剂量选项, unit 单位, freqs 频次选项 }]；WESTERN_OTHER “其他”的单位与频次
 * 中成药：name 药物，doses 单次剂量，unit 单位，freqs 频次
 * 非药物疗法：names 名称，durations 单次时长（分钟），freqs 频次
 */
(() => {
const D3 = ['日1次', '日2次', '日3次'], D2 = ['日1次', '日2次'], D1 = ['日1次'];
/* 西药：药物分类 → 药品（按 PDF 顺序）。非甾体抗炎类药物 PDF 只有药名，无剂量/频次；“其他”手填药品名称 + 用量(mg) + 频次 */
const N1 = ['晚1次'];
const w = (name, doses = [], freqs = [], unit = 'mg') => ({ name, doses, unit: doses.length ? unit : '', freqs });
window.WESTERN_CATALOG = {
  '改善纤维肌痛综合征病情药物': [
    w('普瑞巴林胶囊', ['75', '150', '225'], D2),
    w('苯磺酸美洛加巴林片', ['5', '10', '15'], D2),
    w('苯磺酸克利加巴林胶囊', ['20', '40'], ['日2次']),
    w('加巴喷丁胶囊', ['300'], D3),
    w('盐酸度洛西汀肠溶胶囊', ['20', '30', '40', '60'], D2)
  ],
  '改善焦虑、抑郁药物': [
    w('氟哌噻吨美利曲片', ['1', '2'], D2, '片'),
    w('盐酸阿米替林片', ['25', '50', '75', '100'], D3),
    w('盐酸舍曲林片', ['50', '100', '150', '200'], D1),
    w('草酸艾司西酞普兰片', ['5', '10', '15', '20'], D1),
    w('文拉法辛', ['25', '37.5', '75'], D3)
  ],
  '助眠药': [
    w('右佐匹克隆', ['3'], N1),
    w('酒石酸唑吡坦片', ['10'], N1),
    w('艾司唑仑片', ['1'], N1),
    w('劳拉西泮片', ['1'], N1),
    w('盐酸曲唑酮片', ['50'], D1)
  ],
  '非甾体抗炎类药物': ['布洛芬', '双氯芬酸', '吲哚美辛', '洛索洛芬', '美洛昔康', '萘普生', '塞来昔布', '依托考昔', '对乙酰氨基酚'].map(n => w(n)),
  '肌松药': [
    w('环苯扎林', ['15', '30'], D1),
    w('氯唑沙宗', ['200'], ['日3次'])
  ],
  '其他': []
};
window.WESTERN_OTHER = { unit: 'mg', freqs: ['日1次', '日2次', '日3次', '日4次', '晚1次', '每4小时1次', '每6小时1次', '每12小时1次', '隔日1次', '必要时'] };
const c = (name, doses, unit, freqs) => ({ name, doses, unit, freqs });
window.PATENT_DRUGS = [
  c('乌灵胶囊', ['1', '2', '3'], '粒', D3),
  c('通络开痹片', ['1', '2', '3'], '片', D1),
  c('盘龙七片', ['1', '2', '3', '4'], '片', D3),
  c('祖师麻片', ['1', '2', '3'], '片', D3),
  c('元胡止痛滴丸', ['10', '20', '30'], '丸', D3),
  c('新癀片', ['1', '2', '3', '4'], '片', D3),
  c('金匮肾气丸', ['20', '25'], '粒', D2),
  c('大活络丸', ['1'], '丸', D2),
  c('风湿去痛胶囊', ['5'], '粒', D3),
  c('舒眠胶囊', ['3'], '粒', D2),
  c('疏肝解郁胶囊', ['2'], '粒', D2),
  c('瘀血痹胶囊', ['6'], '粒', D3),
  c('骨康胶囊', ['3', '4'], '粒', D3),
  c('痹祺胶囊', ['4'], '粒', D3),
  c('逍遥丸', ['1', '1.5'], '袋', D2)
];
/* PDF：中成药使用 RA 数据库，但必须包含以上 15 个。宿主页面如注入 window.RA_PATENT_CATALOG（同结构数组），其余药物追加在后，同名以上表为准 */
if (Array.isArray(window.RA_PATENT_CATALOG)) {
  window.RA_PATENT_CATALOG.forEach(d => {
    if (d && d.name && !window.PATENT_DRUGS.some(x => x.name === d.name)) window.PATENT_DRUGS.push(c(String(d.name), (d.doses || []).map(String), d.unit || '', d.freqs || d.frequencies || []));
  });
}
window.NON_DRUG = {
  names: ['太极拳', '八段锦', '针灸', '拔罐', '推拿', '耳针', '中药熏洗', '穴位贴敷', '耳电针', '针刀疗法', '穴位埋线', '刮痧', '揿针', '芳香疗法', '瑜伽', '冥想', '其他'],
  durations: ['5', '10', '15', '20', '25', '30', '35', '40', '45', '50', '55', '60'],
  unit: '分钟',
  freqs: ['日1次', '日2次', '日3次', '隔日1次', '一周1次', '一周2次', '一周3次', '一周4次', '一周5次', '一周6次', '一周7次', '每月1次', '每月2次', '每月3次']
};
window.ADJUST = {
  drug: ['加量', '减量', '停药', '换药'],
  nonDrug: ['增加单次时长', '减少单次时长', '增加频次', '减少频次', '停止当前非药物疗法', '更换非药物疗法'],
  reasons: ['疗效不佳或无效', '症状缓解', '不良反应', '患者自行停用', '经济原因', '治疗方案调整', '疗程结束', '其他']
};
})();
